<?php
require_once __DIR__.'/../app/Core/DB.php';require_once __DIR__.'/../app/Services/KontrakRealisasiService.php';
$db=DB::getInstance();$user=$db->query("SELECT * FROM user_sesendok_biila WHERE kd_wilayah='76.01' AND tahun=2026 AND disable=0 ORDER BY id LIMIT 1")->fetch();if(!$user)$user=['kd_wilayah'=>'76.01','kd_opd'=>'0','tahun'=>2026];$service=new KontrakRealisasiService($user);$ok=static function($v,$m){if(!$v)throw new RuntimeException('FAIL: '.$m);echo "PASS: $m\n";};
$ok(count($service->monthlyFinancialRows())===12,'laporan bulanan selalu memuat 12 bulan');
$realizationReport=$service->financialReportData('realisasi');
$physicalReport=$service->financialReportData('fisik_keuangan',3);
$ok(isset($realizationReport['tahun'],$realizationReport['jumlah_transaksi'],$realizationReport['total_realisasi'])&&is_array($realizationReport['rows']),'laporan Realisasi memakai daftar transaksi realisasi, bukan LRA');
$ok($physicalReport['bulan']===3&&$physicalReport['nama_bulan']==='Maret'&&count($physicalReport['bulan_kumulatif'])===12,'laporan fisik dan keuangan menerima pilihan bulan serta menampilkan rekap kumulatif tahunan');
$ok(is_array($physicalReport['rows'])&&isset($physicalReport['kategori'],$physicalReport['total_realisasi_bulan']),'rincian laporan fisik dan keuangan disajikan terpisah dari ringkasan');
$invalidMonthRejected=false;try{$service->financialReportData('fisik_keuangan',13);}catch(InvalidArgumentException){$invalidMonthRejected=true;}
$ok($invalidMonthRejected,'laporan menolak nomor bulan di luar rentang 1–12');
$invalidReportRejected=false;try{$service->financialReportData('neraca');}catch(InvalidArgumentException){$invalidReportRejected=true;}
$ok($invalidReportRejected,'laporan Realisasi menolak jenis laporan keuangan Neraca');
$lra=$service->lraRows();
foreach(['realisasi','spj','lra','bulanan_fisik_keuangan'] as $format){$file=$service->financialExcel($format);$reader=PhpOffice\PhpSpreadsheet\IOFactory::createReader('Xlsx');$reader->setIncludeCharts(true);$book=$reader->load($file);$sheet=$book->getActiveSheet();$ok($sheet->getCell('A1')->getValue()!==null,"Excel $format memiliki judul resmi");$ok($sheet->getCell('A4')->getValue()==='NO',"Excel $format memiliki header dan total");if($format==='realisasi')$ok(str_contains((string)$sheet->getCell('A1')->getValue(),'LAPORAN REALISASI TAHUN'), 'ekspor Realisasi memakai judul khusus dan bukan format SPJ');if($format==='bulanan_fisik_keuangan'||($format==='lra'&&$lra))$ok(count($sheet->getChartCollection())>=1,"Excel $format memiliki chart");unlink($file);$ok(str_starts_with($service->financialPdf($format),'%PDF'),"PDF $format valid");}
$detailFile=$service->financialExcel('fisik_keuangan_detail',3);$reader=PhpOffice\PhpSpreadsheet\IOFactory::createReader('Xlsx');$detailBook=$reader->load($detailFile);$ok($detailBook->getActiveSheet()->getCell('A4')->getValue()==='NO'&&str_contains((string)$detailBook->getActiveSheet()->getCell('A1')->getValue(),'MARET'),'Excel rincian mengikuti bulan laporan yang dipilih');unlink($detailFile);$ok(str_starts_with($service->financialPdf('fisik_keuangan_detail',3),'%PDF'),'PDF rincian fisik dan keuangan valid');
$summaryFile=$service->financialExcel('fisik_keuangan_ringkasan',3);$reader=PhpOffice\PhpSpreadsheet\IOFactory::createReader('Xlsx');$reader->setIncludeCharts(true);$summaryBook=$reader->load($summaryFile);$ok($summaryBook->getActiveSheet()->getCell('A11')->getValue()==='BULAN'&&str_contains((string)$summaryBook->getActiveSheet()->getCell('A1')->getValue(),'MARET'),'Excel ringkasan memakai bulan yang dipilih');$ok(count($summaryBook->getActiveSheet()->getChartCollection())===2,'Excel tipe 2 menyertakan chart keuangan dan fisik');unlink($summaryFile);$ok(str_starts_with($service->financialPdf('fisik_keuangan_ringkasan',3),'%PDF'),'PDF ringkasan fisik dan keuangan valid');
if($lra){$ok(array_key_exists('pagu',$lra[0])&&array_key_exists('realisasi',$lra[0])&&array_key_exists('sisa',$lra[0]),'LRA memisahkan pagu, realisasi, dan sisa');}
echo "PHASE 19 TESTS COMPLETE\n";
